+  const userId = Number(req.query.user_id);
+  const where = hasUserId ? "user_id = ?" : "user_id IS NOT NULL";
+  const pageParams = hasUserId ? [userId, limit, offset] : [limit, offset];
+  const countParams = hasUserId ? [userId] : [];
+
+  const rows = db
+    .prepare(`SELECT * FROM items WHERE ${where} ORDER BY id LIMIT ? OFFSET ?`)
+    .all(...pageParams) as ItemRow[];
+  const { total } = db
+    .prepare(`SELECT COUNT(*) AS total FROM items WHERE ${where}`)
+    .get(...countParams) as { total: number };
+
+  res.json({ items: rows.map(toDTO), page, limit, total });
